mapper.select:
select
a.ID_, a.PROC_DEF_ID_, a.PROC_INST_ID_, a.EXECUTION_ID_, a.ACT_ID_, a.TASK_ID_, a.CALL_PROC_INST_ID_,
a.ACT_NAME_, a.ACT_TYPE_, (case when b.name is null then '/' else b.name end) ASSIGNEE_, a.START_TIME_, a.END_TIME_, a.DURATION_, a.TENANT_ID_, a.OPTION_, a.REASON_
from act_hi_actinst a left join tb_staff b on (a.ASSIGNEE_=b.staff_id)
where a.PROC_INST_ID_  = #{actId,jdbcType=VARCHAR}
order by a.START_TIME_,a.ID_
